use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut n = self.root
        while n != -1 {
            let k = self.keys[n as usize]
            if x == k { return true }
            if x < k { n = self.left[n as usize] } else { n = self.right[n as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        let id: int = self.keys.len() as int - 1
        if self.root == -1 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            if x < self.keys[n as usize] {
                let l = self.left[n as usize]
                if l == -1 {
                    self.left[n as usize] = id
                    return
                }
                n = l
            } else {
                let r = self.right[n as usize]
                if r == -1 {
                    self.right[n as usize] = id
                    return
                }
                n = r
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n == -1 { return -1 }
        let i = n as usize
        if x < self.keys[i] {
            let r = self.del(self.left[i], x)
            self.left[i] = r
            return n
        }
        if x > self.keys[i] {
            let r = self.del(self.right[i], x)
            self.right[i] = r
            return n
        }
        if self.left[i] == -1 { return self.right[i] }
        if self.right[i] == -1 { return self.left[i] }
        let mut s = self.right[i]
        while self.left[s as usize] != -1 { s = self.left[s as usize] }
        let sk = self.keys[s as usize]
        self.keys[i] = sk
        let r = self.del(self.right[i], sk)
        self.right[i] = r
        n
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        let mut o = out
        if n == -1 { return o }
        o = self.walk(self.left[n as usize], o)
        o.push("${self.keys[n as usize]}")
        o = self.walk(self.right[n as usize], o)
        o
    }

    fn height(self, n: int) -> int {
        if n == -1 { return 0 }
        let a = self.height(self.left[n as usize])
        let b = self.height(self.right[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").map(|s| s.to_string()).collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) {
                let r = t.del(t.root, x)
                t.root = r
                println("ok")
            } else { println("missing") }
        } else if cmd == "inorder" {
            let o = t.walk(t.root, [])
            if o.len() == 0 { println("<empty>") } else { println(o.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 { println("empty") } else {
                let mut n = t.root
                while t.left[n as usize] != -1 { n = t.left[n as usize] }
                println("${t.keys[n as usize]}")
            }
        } else if cmd == "max" {
            if t.root == -1 { println("empty") } else {
                let mut n = t.root
                while t.right[n as usize] != -1 { n = t.right[n as usize] }
                println("${t.keys[n as usize]}")
            }
        }
    }
}

